+using System.Text.RegularExpressions;
+
+namespace DocSummary.Services;
+
+/// <summary>
+/// Extractive summarizer that scores sentences by word frequency and returns the top-ranked ones.
+/// </summary>
+public partial class DocumentSummarizer
+{
+    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
+    {
+        "a","an","the","and","or","but","is","are","was","were","be","been","being",
+        "have","has","had","do","does","did","will","would","shall","should","may",
+        "might","must","can","could","i","you","he","she","it","we","they","me",
+        "him","her","us","them","my","your","his","its","our","their","this","that",
+        "these","those","in","on","at","to","for","of","with","by","from","as","into",
+        "about","between","through","during","before","after","above","below","not","no",
+        "so","if","then","than","too","very","just","also","more","most","some","any",
+        "each","every","all","both","few","many","much","own","other","another","such",
+        "what","which","who","whom","how","when","where","why","while","up","out","off"
+    };
+
+    public string Summarize(string text, int maxSentences)
+    {
+        var sentences = SplitSentences(text);
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        var wordFrequencies = ComputeWordFrequencies(sentences);
+        var scored = sentences
+            .Select((sentence, index) => (Sentence: sentence, Score: ScoreSentence(sentence, wordFrequencies), Index: index))
+            .OrderByDescending(s => s.Score)
+            .Take(maxSentences)
+            .OrderBy(s => s.Index) // preserve original order
+            .Select(s => s.Sentence);
+
+        return string.Join(" ", scored);
+    }
+
+    private static List<string> SplitSentences(string text)
+    {
+        return SentenceRegex()
+            .Split(text)
+            .Select(s => s.Trim())
+            .Where(s => s.Length > 0)
+            .ToList();
+    }
+
+    private static Dictionary<string, int> ComputeWordFrequencies(List<string> sentences)
+    {
+        var frequencies = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in ExtractWords(sentence))
+            {
+                if (!StopWords.Contains(word))
+                    frequencies[word] = frequencies.GetValueOrDefault(word) + 1;
+            }
+        }
+        return frequencies;
+    }
+
+    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
+    {
+        var words = ExtractWords(sentence);
+        if (words.Count == 0) return 0;
+
+        double score = 0;
+        foreach (var word in words)
+        {
+            score += wordFrequencies.GetValueOrDefault(word);
+        }
+        return score / words.Count;
+    }
+
+    private static List<string> ExtractWords(string text)
+    {
+        return WordRegex()
+            .Matches(text)
+            .Select(m => m.Value)
+            .ToList();
+    }
+
+    public static int CountWords(string text) => WordRegex().Matches(text).Count;
+
+    [GeneratedRegex(@"(?<=[.!?])\s+")]
+    private static partial Regex SentenceRegex();
+
+    [GeneratedRegex(@"\b[a-zA-Z0-9]+\b")]
+    private static partial Regex WordRegex();
+}
